import React, { useState } from "react";
import Login from "./components/login";
import IncomeCategory from "./components/IncomeCategory";
import SpendingPriority from "./components/SpendingPriority";
import BudgetLimits from "./components/BudgetLimits";
import Dashboard from "./components/Dashboard";
import Preview from "./components/Preview";
import Questionnaire from "./components/Questionnaire";

function App() {
  const [step, setStep] = useState("login");

  const [data, setData] = useState({
    income: "",
    questionnaire: {},   // ✅ store questionnaire separately
    categories: [],      // ✅ from SpendingPriority
    limits: {}           // ✅ from BudgetLimits
  });

  return (
    <>
      {/* LOGIN */}
      {step === "login" && (
        <Login onLogin={() => setStep("income")} />
      )}

      {/* INCOME */}
      {step === "income" && (
        <IncomeCategory
          onNext={(val) => {
            setData({ ...data, income: val });
            setStep("questionnaire");
          }}
        />
      )}

      {/* QUESTIONNAIRE ✅ FIXED */}
      {step === "questionnaire" && (
        <Questionnaire
          data={data.questionnaire}
          onNext={(answers) => {
            setData({ ...data, questionnaire: answers }); // ✅ FIX HERE
            setStep("priority");
          }}
          onBack={() => setStep("income")}
        />
      )}

      {/* SPENDING PRIORITY ✅ FIXED */}
      {step === "priority" && (
        <SpendingPriority
          selected={data.categories}
          onNext={(categories) => {
            setData({ ...data, categories }); // ✅ categories stored here
            setStep("budget");
          }}
          onBack={() => setStep("questionnaire")}
        />
      )}

      {/* BUDGET */}
      {step === "budget" && (
  <BudgetLimits
    selectedCategories={data.categories}
    onNext={(limits) => {
      setData(prev => ({ ...prev, limits }));
      setStep("preview");
    }}
    onBack={() => setStep("priority")}
  />
)}

      {/* PREVIEW */}
      {step === "priority" && (
  <SpendingPriority
    selected={data.categories}
    onNext={(categories) => {
      setData({ ...data, categories });
      setStep("budget");
    }}
    onBack={() => setStep("questionnaire")}   // ✅ REQUIRED
  />
)}

      {/* DASHBOARD */}
      {step === "dashboard" && (
        <Dashboard />
      )}
    </>
  );
}

export default App;
